from mkgen import *
T=[]; A=lambda *x,**k: a(T,*x,**k)
A(r"Найдите наибольший целый ответ неравенства \(-3\le\dfrac{2x-7}{3}<2\).",r"\(-3\le\dfrac{2x-7}{3}<2\) теңсіздігінің ең үлкен бүтін шешімін табыңыз.",["5","6","7","0"],"B","−9 ≤ 2x − 7 < 6 → −1 ≤ x < 6,5. Наибольшее целое 6.")
A("Найдите масштаб карты, если расстоянию между двумя городами 120 км на карте соответствует 6 мм.","Екі қала арасындағы 120 км қашықтық картада 6 мм болса, картаның масштабын табыңыз.",["1 : 400 000 000","1 : 20 000 000","1 : 2 000 000","1 : 50 000 000"],"B","120 км = 120 000 000 мм; 120 000 000 : 6 = 20 000 000.")
A("Охотники с собаками находятся в 600 метрах от оленя. Скорость оленя 10 м/с, а собак 14 м/с. На каком расстоянии будут собаки от оленя через 2 минуты?","Аңшылар иттерімен бұғыдан 600 м қашықтықта. Бұғының жылдамдығы 10 м/с, иттердікі 14 м/с. 2 минуттан кейін иттер бұғыдан қандай қашықтықта болады?",["480 м","100 м","120 м","140 м"],"C","Сближение 4 м/с, за 120 с — 480 м. Остаётся 600 − 480 = 120 м.")
A("Найдите площадь прямоугольника, состоящего из 12 одинаковых квадратов, сумма периметров которых равна 144 см.","Қосындысы 144 см периметрлі 12 бірдей шаршыдан тұратын тіктөртбұрыштың ауданын табыңыз.",["48 см²","36 см²","108 см²","120 см²"],"C","Периметр одного 12 см, сторона 3 см, площадь 9 см²; 12·9 = 108 см².")
A("Найдите число, полученное умножением числа, обратного 20, и числа, противоположного (−15).","20 санына кері сан мен (−15) санына қарама-қарсы санды көбейтіп алынған санды табыңыз.",["−300","2,5","0,75","0,2"],"C","(1/20)·15 = 0,75.")
A("Адель привезла подругам подарки: 24 браслета, 36 заколок и 60 цепочек. Она раздаёт одинаковые подарки, используя всё. Сколько вещей в одном подарке?","Адель құрбыларына сыйлық әкелді: 24 білезік, 36 шашқап және 60 алқа. Ол барлығын пайдаланып, бірдей сыйлықтар таратады. Бір сыйлықта қанша зат бар?",["27","10","5","12"],"B","НОД(24, 36, 60) = 12 подарков; в каждом 2 + 3 + 5 = 10 вещей.")
A("На координатной прямой A(−4), B(2), C(7). Укажите неправильное утверждение.","Координаталық түзуде A(−4), B(2), C(7). Қате тұжырымды көрсетіңіз.",[r"\(|AB|<2|BC|\)",r"\(12>|AB|\)",r"\(|BC|\ge2{,}8\)",r"\(|AB|>|-13|\)"],"D","|AB| = 6, |BC| = 5. Утверждение D (6 > 13) неверно.")
A(r"Найдите отношение \(x\) к \(y\), если \(\dfrac{2{,}5x}{3}=4\) и \(\dfrac49y:1\tfrac13=4:3\tfrac37\).",r"\(\dfrac{2{,}5x}{3}=4\) және \(\dfrac49y:1\tfrac13=4:3\tfrac37\) болса, \(x\) пен \(y\) қатынасын табыңыз.",["2,2",r"\(1\tfrac57\)",r"\(2\tfrac17\)",r"\(1\tfrac{13}{35}\)"],"D","x = 4,8. y/3 = 4 : 24/7 = 7/6, y = 3,5. x : y = 4,8 : 3,5 = 48/35 = 1 13/35.")
A("Бригада из 6 рабочих строит крышу за 20 дней. Сколько ещё рабочих нужно пригласить, чтобы сделать это задание за 8 дней?","6 жұмысшыдан тұратын бригада төбені 20 күнде салады. Жұмысты 8 күнде жасау үшін тағы қанша жұмысшы шақыру керек?",["5","6","9","3"],"C","6·20 = 120 человеко-дней; 120 : 8 = 15 человек, ещё 9.")
A("К 300 г солевого раствора с концентрацией 20% добавили 100 г воды. Найдите процент соли в полученном растворе.","Концентрациясы 20% 300 г тұзды ерітіндіге 100 г су қосты. Алынған ерітіндідегі тұз пайызын табыңыз.",["20%","15%","12,5%","60%"],"B","Соли 60 г; масса 400 г; 60 : 400 = 15%.")
A("Число 700 разделили на 3 части пропорционально числам 2, 3 и 5. Найдите разницу между средним и самым маленьким числом.","700 санын 2, 3 және 5 сандарына пропорционал 3 бөлікке бөлді. Ортаңғы және ең кіші сандардың айырмасын табыңыз.",["70","140","210","350"],"A","Часть 70: числа 140, 210, 350. 210 − 140 = 70.")
A(r"Найдите упрощённый вид: \(-\left(8\tfrac12x+6{,}3y-5z\right)-2(-4{,}25x-2z-4{,}45y)\).",r"Ықшамдалған түрін табыңыз: \(-\left(8\tfrac12x+6{,}3y-5z\right)-2(-4{,}25x-2z-4{,}45y)\).",["5(z − 2,4y)","3z − 2,6y","9z + 2,6y","1,2(0,5x − 1,6y)"],"C","−8,5x − 6,3y + 5z + 8,5x + 4z + 8,9y = 9z + 2,6y.")
A("Чтобы покрасить поверхность куба с ребром 4 см, нужно 48 г краски. Сколько нужно краски, чтобы покрасить куб с ребром 6 см?","Қыры 4 см кубтың бетін бояуға 48 г бояу керек. Қыры 6 см кубты бояуға қанша бояу керек?",["72 г","108 г","54 г","90 г"],"B","Площадь 96 см² → 48 г, значит 0,5 г/см². Куб 6 см: 216 см² → 108 г.")
A("Общая масса банана и яблока 360 г, яблока и апельсина 400 г, банана и апельсина 440 г. Найдите массу апельсина.","Банан мен алманың жалпы массасы 360 г, алма мен апельсинніңкі 400 г, банан мен апельсинніңкі 440 г. Апельсиннің массасын табыңыз.",["140 г","240 г","180 г","200 г"],"B","Сумма всех трёх: (360 + 400 + 440) : 2 = 600 г. Апельсин: 600 − 360 = 240 г.")
A(r"Найдите процентное значение дроби \(\dfrac{4{,}5a^2}{30a^2}\).",r"\(\dfrac{4{,}5a^2}{30a^2}\) бөлшегінің пайыздық мәнін табыңыз.",["35%","70%","15%","28%"],"C","4,5 : 30 = 0,15 = 15%.")
A(r"Диана за год прочитала 15 книг, это составляет \(\tfrac34\) книг, прочитанных за год Асемгуль. Сколько книг прочитали вместе подруги?",r"Диана бір жылда 15 кітап оқыды, бұл Әсемгүл бір жылда оқыған кітаптардың \(\tfrac34\) бөлігін құрайды. Құрбылар бірге қанша кітап оқыды?",["24","35","36","30"],"B","Асемгуль: 15 : 3/4 = 20; вместе 35.")
A(r"Найдите больший из корней уравнения \(\dfrac{|-2x+5|}3=\dfrac{11{,}9}{1{,}7}\).",r"\(\dfrac{|-2x+5|}3=\dfrac{11{,}9}{1{,}7}\) теңдеуінің үлкен түбірін табыңыз.",["8","13","−8","10"],"B","|−2x + 5| = 21: x = −8 или x = 13. Больший — 13.")
A("Все книги школьной библиотеки на русском, казахском и английском языках, отношение их количеств 9 : 5 : 6. Сколько процентов всех книг составляют книги на казахском языке?","Мектеп кітапханасындағы барлық кітап орыс, қазақ және ағылшын тілдерінде, олардың саны 9 : 5 : 6 қатынасындай. Қазақ тіліндегі кітаптар барлық кітаптың неше пайызын құрайды?",["30%","25%","55%","21%"],"B","Всего 20 частей, казахских 5: 5/20 = 25%.")
A("Длину прямоугольника уменьшили на 20%. На сколько процентов нужно увеличить ширину, чтобы площадь осталась неизменной?","Тіктөртбұрыштың ұзындығын 20%-ға кеміткен. Ауданы өзгермеуі үшін енін неше пайызға арттыру керек?",["20%","25%","100%","62,5%"],"B","Длина ×0,8, значит ширина ×1/0,8 = 1,25 — увеличить на 25%.")
A("В трёх шестых классах 30 отличников. Число отличников в «6А» на 5 меньше, чем в «6Б», а в «6В» в 2 раза меньше, чем в «6Б». Сколько отличников в «6В»?","Үш алтыншы сыныпта 30 үздік оқушы бар. «6А»-да «6Б»-ға қарағанда 5 кем, ал «6В»-да «6Б»-ға қарағанда 2 есе аз. «6В»-да қанша үздік оқушы бар?",["12","7","10","16"],"B","Пусть в 6Б b: (b − 5) + b + b/2 = 30 → 2,5b = 35, b = 14, в 6В 7.")
A(r"Если \(\dfrac4{3x-6}=\dfrac2{x+1}\), то чему равно значение \(7x-11\)?",r"\(\dfrac4{3x-6}=\dfrac2{x+1}\) болса, \(7x-11\) мәні неге тең?",["45","56","35","40"],"A","4x + 4 = 6x − 12 → x = 8; 7·8 − 11 = 45.")
A(r"Найдите квадрат ответа выражения \(\dfrac{-4{,}8\cdot6{,}5\cdot1{,}2}{6\cdot4{,}8\cdot(-2{,}6)}\).",r"\(\dfrac{-4{,}8\cdot6{,}5\cdot1{,}2}{6\cdot4{,}8\cdot(-2{,}6)}\) өрнегі жауабының квадратын табыңыз.",["9","0,(1)",r"\(\tfrac12\)","0,25"],"D","Числитель −37,44, знаменатель −74,88: дробь 1/2; квадрат 1/4 = 0,25.")
A(r"Решите неравенство: \(\dfrac{x-3}6-\dfrac{2x-3}3\le-\dfrac{2{,}5}{0{,}5}\).",r"Теңсіздікті шешіңіз: \(\dfrac{x-3}6-\dfrac{2x-3}3\le-\dfrac{2{,}5}{0{,}5}\).",[r"\(x\in(-\infty;11)\)",r"\(x\in[-11;+\infty)\)",r"\(x\in(11;+\infty)\)",r"\(x\in[11;+\infty)\)"],"D","Умножим на 6: x − 3 − 4x + 6 ≤ −30 → −3x ≤ −33 → x ≥ 11.")
A("Назовите угол, \\(\\tfrac35\\) которого составляют 54°.","\\(\\tfrac35\\) бөлігі 54° болатын бұрышты атаңыз.",["острый угол","прямой угол","тупой угол","развёрнутый угол"],"B","54 : 3/5 = 90° — прямой угол.",ok=["сүйір бұрыш","тік бұрыш","доғал бұрыш","жазыңқы бұрыш"])
A(r"Как изменится значение выражения \(k:t\), если его делимое увеличить в 3 раза, а делитель уменьшить вдвое?",r"\(k:t\) өрнегінің бөлінгішін 3 есе арттырып, бөлгішін екі есе кемітсе, оның мәні қалай өзгереді?",["увеличится в 5 раз","уменьшится в 4 раза","увеличится в 6 раз","увеличится в 3 раза"],"C","3 : 1/2 = 6 — значение увеличится в 6 раз.",ok=["5 есе артады","4 есе азаяды","6 есе артады","3 есе артады"])
A("В механизме часов две шестерёнки вращаются друг с другом. Когда меньшая делает 80 оборотов, большая делает 48. Если длина окружности большей шестерёнки равна 30 мм, найдите длину окружности меньшей.","Сағат механизмінде екі тісті доңғалақ бір-бірімен айналады. Кіші доңғалақ 80 айналым жасағанда, үлкені 48 айналым жасайды. Үлкен доңғалақ шеңберінің ұзындығы 30 мм болса, кішісінің ұзындығын табыңыз.",["12 мм","18 мм","24 мм","2 см"],"B","Пройденная длина по зацеплению одинакова: 48·30 = 1440 мм = 80·c, c = 18 мм.")
A("Сумма 4 последовательных целых чисел равна −10. Найдите наименьшее из этих чисел.","Қатарлас 4 бүтін санның қосындысы −10. Осы сандардың ең кішісін табыңыз.",["−4","−5","−1","2"],"A","4n + 6 = −10 → n = −4.")
A(r"Вычислите: \((-2)^3+2^5-2^4-1\tfrac14\).",r"Есептеңіз: \((-2)^3+2^5-2^4-1\tfrac14\).",["3","−0,25","6,75","15,25"],"C","−8 + 32 − 16 − 1,25 = 6,75.")
A(r"Найдите следующее число последовательности: \(7{,}5;\ 5;\ 3\tfrac13;\ 2\tfrac29;\ \ldots\)",r"Тізбектің келесі санын табыңыз: \(7{,}5;\ 5;\ 3\tfrac13;\ 2\tfrac29;\ \ldots\)",[r"\(\tfrac{80}{81}\)",r"\(\tfrac{40}{27}\)",r"\(\tfrac{20}{21}\)",r"\(\tfrac{12}{23}\)"],"B","Каждый член умножается на 2/3: 2 2/9 · 2/3 = 20/9·2/3 = 40/27.")
A("Найдите диаметр колеса машины, если при пройденном пути 314 м колесо сделало 250 оборотов (π = 3,14).","Жүрілген жол 314 м болғанда дөңгелек 250 айналым жасаса, көлік дөңгелегінің диаметрін табыңыз (π = 3,14).",["60 см","40 см","2 м","30 см"],"B","Длина окружности 314 : 250 = 1,256 м; d = 1,256 : 3,14 = 0,4 м = 40 см.")
A(r"Две прямые пересекаются. Один из углов равен \(128^\circ\); \(x\) — смежный с ним, \(y\) — вертикальный ему. Найдите \(x-y\).",r"Екі түзу қиылысады. Бір бұрышы \(128^\circ\); \(x\) — оған көршілес, \(y\) — оған вертикаль. \(x-y\) табыңыз.",[r"\(76^\circ\)",r"\(52^\circ\)",r"\(-52^\circ\)",r"\(-76^\circ\)"],"D","x = 180° − 128° = 52°, y = 128°; x − y = −76°.")
A(r"Вычислите: \(\dfrac{0{,}6}{10}+\dfrac3{0{,}15}-\dfrac{0{,}04}2\).",r"Есептеңіз: \(\dfrac{0{,}6}{10}+\dfrac3{0{,}15}-\dfrac{0{,}04}2\).",["20","19,99","20,04","0,01"],"C","0,06 + 20 − 0,02 = 20,04.")
A(r"Верблюд шёл три дня по пустыне к воде. В первый день он прошёл 50% пути, во второй день \(\tfrac25\) от пройденного в первый день. В третий день, пройдя 30 км, добрался до воды. Найдите весь путь.",r"Нар үш күн шөлмен суға қарай жүрді. Бірінші күні жолдың 50%-ын, екінші күні бірінші күні жүргенінің \(\tfrac25\) бөлігін жүрді. Үшінші күні 30 км жүріп, суға жетті. Бүкіл жолды табыңыз.",["90 км","100 км","108 км","72 км"],"B","Во второй день 20%; в третий 30% = 30 км, значит весь путь 100 км.")
A("A и B — нечётные числа. Результат какого варианта является чётным числом?","A және B — тақ сандар. Қай нұсқаның нәтижесі жұп сан?",["2A + B","3A + B","A · B","A − 2B"],"B","3A нечётное + B нечётное = чётное. Остальные нечётные.")
A("Первая труба наполняет бассейн за 10 часов, вторая за 15. За сколько времени две трубы вместе наполняют \\(\\tfrac34\\) бассейна?","Бірінші құбыр бассейнді 10 сағатта, екіншісі 15 сағатта толтырады. Екі құбыр бірге бассейннің \\(\\tfrac34\\) бөлігін қанша уақытта толтырады?",["3 часа","4,5 часа","5 часов","6 часов"],"B","Вместе 1/10 + 1/15 = 1/6 в час. 3/4 : 1/6 = 4,5 часа.",ok=["3 сағат","4,5 сағат","5 сағат","6 сағат"])
A("Вычислите: \\(-(-(-(-4{,}5+(-(-2{,}6-3{,}4)))))\\).","Есептеңіз: \\(-(-(-(-4{,}5+(-(-2{,}6-3{,}4)))))\\).",["1,5","10,5","−1,5","−10,5"],"C","−2,6 − 3,4 = −6; −(−6) = 6; −4,5 + 6 = 1,5; три внешних минуса дают −1,5.")
A("В магазине электротехники 60 видов ламп и 36 видов люстр. Во сколько раз ламп больше, чем люстр?","Электротехника дүкенінде лампаның 60 түрі және люстраның 36 түрі бар. Лампалар люстралардан неше есе көп?",[r"\(2\tfrac25\)",r"\(1\tfrac23\)",r"\(\tfrac7{12}\)",r"\(\tfrac12\)"],"B","60 : 36 = 5/3 = 1 2/3.")
A("Цена футболки 4000 тг. В магазине объявили скидку 15%. Сколько стала стоить футболка?","Футболканың бағасы 4000 тг. Дүкенде 15% жеңілдік жарияланды. Футболка қанша тұрады?",["3400 тг","3600 тг","3000 тг","600 тг"],"A","4000·0,85 = 3400.")
A("Периметр прямоугольника равен 30 см, длина 9 см. Найдите его площадь.","Тіктөртбұрыштың периметрі 30 см, ұзындығы 9 см. Оның ауданын табыңыз.",["54 см²","45 см²","60 см²","36 см²"],"A","Ширина 15 − 9 = 6; площадь 9·6 = 54.")
A("В треугольнике два угла равны 50° и 65°. Найдите третий угол.","Үшбұрышта екі бұрыш 50° және 65°. Үшінші бұрышты табыңыз.",["55°","65°","75°","115°"],"B","180° − 50° − 65° = 65°.")
write(T,"T04_MATH","t04-math.ts","Тест 4 · Математика")
